function дисперсия(данные) {
  if (данные.length === 0) return null;
  const среднее = данные.reduce((сумма, значение) => сумма + значение, 0) / данные.length;
  return данные.reduce((сумма, значение) => сумма + (значение - среднее) ** 2, 0) / данные.length;
}
console.log(дисперсия([2, 4, 6]));
